SELECT id, title, source_type, author, edition, url, note FROM jsonb_populate_recordset(NULL::public.source, '[{"title": "旧五代史·卷一百", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/44b0593aeab837b5fbc1263a74f880f3ba1b4acb/content/books/zizhi-tongjian/vol-287/year-0947/part-04/sources/library/jiuwudaishi-100-july-transfers/source.txt", "note": "《旧五代史》卷一百，段落 jiu-wudaishi-205deb4a7860-p002436；EPUB电子本，纸本及异文待核", "id": "730295ed-42b9-5013-95c3-02b9a659dd24"}, {"title": "旧五代史·卷一百二十五", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/44b0593aeab837b5fbc1263a74f880f3ba1b4acb/content/books/zizhi-tongjian/vol-287/year-0947/part-04/sources/library/jiuwudaishi-125-wang-jihong/source.txt", "note": "《旧五代史》卷一百二十五，段落 jiu-wudaishi-205deb4a7860-p002920；EPUB电子本，纸本及异文待核", "id": "27299071-b5fe-5f25-b2f7-e8391c8589b9"}, {"title": "辽史·卷五", "source_type": "primary", "author": "脱脱等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/44b0593aeab837b5fbc1263a74f880f3ba1b4acb/content/books/zizhi-tongjian/vol-287/year-0947/part-04/sources/library/liaoshi-005-june-vanguard/source.txt", "note": "《辽史》卷五，段落 liaoshi-7cd182a20e67-p000592；EPUB电子本，纸本及异文待核", "id": "152751a0-1874-557b-81cd-d2027f01a861"}, {"title": "辽史·卷五", "source_type": "primary", "author": "脱脱等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/44b0593aeab837b5fbc1263a74f880f3ba1b4acb/content/books/zizhi-tongjian/vol-287/year-0947/part-04/sources/library/liaoshi-005-shulu-confrontation/source.txt", "note": "《辽史》卷五，段落 liaoshi-7cd182a20e67-p000593；EPUB电子本，纸本及异文待核", "id": "8388690b-7d10-5c45-a2dd-22cd6ac13f96"}, {"title": "辽史·卷五", "source_type": "primary", "author": "脱脱等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/44b0593aeab837b5fbc1263a74f880f3ba1b4acb/content/books/zizhi-tongjian/vol-287/year-0947/part-04/sources/library/liaoshi-005-tianlu-titles/source.txt", "note": "《辽史》卷五，段落 liaoshi-7cd182a20e67-p000595；EPUB电子本，纸本及异文待核", "id": "7d7b1e3e-615d-5e28-bef9-8d2a3d7eeac3"}, {"title": "辽史·卷七十六", "source_type": "primary", "author": "脱脱等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/44b0593aeab837b5fbc1263a74f880f3ba1b4acb/content/books/zizhi-tongjian/vol-287/year-0947/part-04/sources/library/liaoshi-076-zhao-yanshou-death/source.txt", "note": "《辽史》卷七十六，段落 liaoshi-7cd182a20e67-p005111；EPUB电子本，纸本及异文待核", "id": "dfa3c487-5ef5-5f91-a8ed-93d84e5fdbc7"}, {"title": "资治通鉴·后汉纪二", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/44b0593aeab837b5fbc1263a74f880f3ba1b4acb/content/books/zizhi-tongjian/vol-287/year-0947/part-04/sources/library/tongjian-287-947-june-july-governors/source.txt", "note": "《资治通鉴》后汉纪二，段落 zizhi-tongjian-a63549944a71-p003407；电子底本待考，分段待核", "id": "5595ed79-f507-5f3b-863b-dfbb9293440f"}, {"title": "资治通鉴·后汉纪二", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/cb7c4e8e14cca0f06693158578b4b0287925c9b1/content/books/zizhi-tongjian/vol-287/year-0947/part-02/sources/library/tongjian-287-947-jinzhou-north-return/source.txt", "note": "《资治通鉴》后汉纪二，段落 zizhi-tongjian-a63549944a71-p003406；电子底本待考，分段待核", "id": "b4721b35-1a13-5f3c-903a-56c304cad0e9"}, {"title": "旧五代史·卷一百", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/727493791cbf73933108431c692275b3b8c9af2b/content/books/zizhi-tongjian/vol-287/year-0947/part-03/sources/library/jiuwudaishi-100-june-arrivals/source.txt", "note": "《旧五代史》卷一百，段落 jiu-wudaishi-205deb4a7860-p002435；EPUB电子本，纸本及异文待核", "id": "31f5f807-cf99-512a-bfd0-515a744a415a"}, {"title": "新五代史·卷六十七", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/727493791cbf73933108431c692275b3b8c9af2b/content/books/zizhi-tongjian/vol-287/year-0947/part-03/sources/library/xinwudaishi-067-qian-zong-succession/source.txt", "note": "《新五代史》卷六十七，段落 xin-wudaishi-b08f244b9241-p003375；EPUB电子本，纸本及异文待核", "id": "6bc7a35e-fa90-5b15-8ce4-7a044f9b0446"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "钱弘倧", "aliases": ["錢弘倧"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "钱传瓘之子，母亲鹿氏。939年条下的王室家属追述提及他，出生年份本句未载。", "biography": null, "status": "draft", "id": "141c421e-2a7d-5b59-91f9-bf5ec3f726df"}, {"name": "刘知远", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷271贞明五年条所见人物：刘知远。", "biography": null, "status": "draft", "id": "69fa3b4b-2f0d-5799-bbf5-e378af9816e1"}, {"name": "刘崇（刘知远弟）", "aliases": ["劉崇（劉知遠弟）", "刘旻", "劉旻"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "刘知远的弟弟，后来名刘旻。947年任太原尹、知府事。与朱温早年寄居的萧县刘崇分别建档，具体生卒年尚未录入。", "biography": null, "status": "draft", "id": "edf0bd63-ab6d-577e-8623-9f2d759b6d97"}, {"name": "述律平", "aliases": ["述律氏", "述律后", "述律皇后"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷269贞明二年条所见人物：述律平。", "biography": null, "status": "draft", "id": "1c865dcb-3259-50e9-b13e-181615308183"}, {"name": "耶律阮", "aliases": ["耶律兀欲", "兀欲", "永康王"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "小字兀欲，东丹王耶律倍之子。《资治通鉴》947年条下称永康王，记耶律德光将李彦绅、秦继旻的家属和财产交给他。《辽史》卷五明确名阮、小字兀欲，按同一主体建档；王号具体授封时间仍须另据后文校核，生卒年暂未录。", "biography": null, "status": "draft", "id": "42a17de5-aa28-50e6-bab8-b134f0113f3f"}, {"name": "伟王（契丹）", "aliases": ["偉王（契丹）"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "契丹王爵称谓，个人姓名在本批史料中未明确。944年正月辛丑，太原奏报在秀容击败其军；《新五代史》记与其交战的晋方将领为刘知远。生卒年未载。", "biography": null, "status": "draft", "id": "c66b0ad9-97a7-5581-809d-b343a2101358"}, {"name": "李彦韬（后晋宣徽使）", "aliases": ["李彥韜（後晉宣徽使）"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "太原人，早年曾侍奉阎宝，后来入石敬瑭帐下并留在太原侍奉石重贵。945年任宣徽北院使、暂代侍卫马步都虞候，与冯玉争桑维翰的权力。与早期曾名李彦韬的温韬分档，温韬在后唐明宗时已被赐死。生卒年本段未载。", "biography": null, "status": "draft", "id": "e4ac4a2d-843f-5686-98da-4b16e23f906d"}, {"name": "高勋", "aliases": ["高勛"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后晋阁门使。946年十二月丙寅，杜重威派他向契丹送降表，耶律德光赐诏接受。与军将关勋分别识别；生卒年本批未核。", "biography": null, "status": "draft", "id": "ea4f636d-1bb8-5b40-a94d-0da7caf7ebea"}, {"name": "耶律德光", "aliases": ["德光"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷275同光四年条所见人物：耶律德光，守西楼、受号者。", "biography": null, "status": "draft", "id": "64c415ac-57fe-571c-8c6f-3ed68fb726da"}, {"name": "王继弘", "aliases": ["王繼弘", "王继宏", "王繼宏"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后汉相州节度使。《资治通鉴》记他后来收葬相州城中遗骨；《旧五代史》作王继宏，将发现遗骨记在乾祐年间。生卒年未载。", "biography": null, "status": "draft", "id": "c58b8745-38bc-50f1-9770-848f81d79849"}, {"name": "樊晖", "aliases": ["樊暉"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "947年任奉国军都虞候，随王继弘驻相州，与王继弘杀高唐英。六月庚辰获任磁州刺史。《旧五代史》王继宏传作樊暉，本纪相关杀人条作楚暉，字形差异保留待核。生卒年未载。", "biography": null, "status": "draft", "id": "887e1a5e-f098-51e8-a01c-b476e4defa3f"}, {"name": "高唐英", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "契丹所任地方长官。947年二月刘知远即位后，被任命为彰德节度使；梁晖袭取相州时，他尚未到任。《旧五代史》同记相州節度使，《辽史》官号另作昭德，分别保留。生卒年未载。", "biography": null, "status": "draft", "id": "4b35bffc-c928-554e-8e55-22b4618620ab"}, {"name": "高奉明", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "原任武州刺史。947年五月，耶律阮北归前任命他为安国节度使。生卒年未载。", "biography": null, "status": "draft", "id": "3583b089-97ec-5a72-abac-640a761b3642"}, {"name": "麻答", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "契丹将领，《资治通鉴》称为耶律德光的从弟。944年二月由周儒引导从马家口渡河，攻郓州北津，以接应杨光远。个人其他名字及生卒年本批未核。", "biography": null, "status": "draft", "id": "5911d4cb-fa8a-51ff-a1e4-44450396116a"}, {"name": "刘铎", "aliases": ["劉鐸"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "947年任马步都指挥使。安国节度使高奉明离镇前，请麻答安排刘铎为节度副使、主持军府事务。生卒年未载。", "biography": null, "status": "draft", "id": "c7572e9d-46d8-5572-a786-fee85988afdb"}, {"name": "高从诲", "aliases": ["高從誨"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷273同光三年条所见人物：高从诲。", "biography": null, "status": "draft", "id": "361de308-8df0-56e4-ac98-81f6b9297e26"}, {"name": "李璟", "aliases": ["徐景通", "景通", "李景"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷272同光元年条所见人物：李璟。", "biography": null, "status": "draft", "id": "6bf72971-88c3-5187-8f25-98cde2a9554a"}, {"name": "李金全", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：李金全，前节度使、多次献马者。", "biography": null, "status": "draft", "id": "13205047-3c88-59d8-9900-ef435bd6e59a"}, {"name": "马希广", "aliases": ["馬希廣", "德丕"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：马希广，武安节度副使，临时领府者。", "biography": null, "status": "draft", "id": "eb8e4d76-8384-56ed-a225-77675cfd8927"}, {"name": "郭威", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷272同光元年条所见人物：郭威。", "biography": null, "status": "draft", "id": "3fe84db3-aa25-5be9-9dd3-8b46e28213af"}, {"name": "赵匡赞", "aliases": ["趙匡贊"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "赵延寿的儿子。947年正月受耶律德光任命为护国节度使。生卒年未载。", "biography": null, "status": "draft", "id": "ad59529e-c641-5bb7-bde5-3749239fd1d3"}, {"name": "杜重威", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "朔州人，后晋将领，妻子是石敬瑭的妹妹乐平长公主。937年以护圣都指挥使身份率军驻卫州。", "biography": null, "status": "draft", "id": "e5e23c10-447f-5238-bc56-f376300f9bac"}, {"name": "李守贞", "aliases": ["李守貞"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后晋内客省使。940年五月受命担任马全节讨伐李金全军队的都监，职务由《旧五代史》本纪补充。生卒年未据本段确定。", "biography": null, "status": "draft", "id": "a3d16959-684f-5c82-b848-8dcbdc73e85a"}, {"name": "高行周", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷268乾化三年条所见人物：高行周。", "biography": null, "status": "draft", "id": "659c5f83-09bc-5282-8f02-4c7fa0a62729"}, {"name": "赵延寿", "aliases": ["趙延壽", "延寿"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷275同光四年条所见人物：赵延寿，公主丈夫。", "biography": null, "status": "draft", "id": "bf502cd0-4cbb-52e5-b93a-e30caa907a58"}, {"name": "钱弘俶", "aliases": ["钱俶", "錢俶", "錢弘俶"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "钱传瓘之子，母亲吴氏。《宋史》本传明确本名弘俶，后名钱俶；《资治通鉴》所用电子本在王室家属追述中把俶写作拆分字形。生卒年暂未录全。", "biography": null, "status": "draft", "id": "3a65648c-82a5-5d66-be49-1fbc1ccb4e70"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

